def mostCompetitive(nums, k):
    stack = []
    n = len(nums)
    for i, num in enumerate(nums):
        # While stack not empty, last element is bigger, and we have enough left to fill k
        while stack and num < stack[-1] and len(stack) + (n - i) > k:
            stack.pop()
        if len(stack) < k:
            stack.append(num)
    return stack
